import React from "react";
import { Routes, Route } from "react-router-dom"; // Keep Routes and Route here
import "./App.css";
import InputMeal from "./components/InputMeal";
import SearchFood from "./components/SearchFood";
import DailyGoals from "./components/DailyGoals";
import WeeklyReports from "./components/WeeklyReports";
import Suggestions from "./components/Suggestions";
import NavigationBar from "./components/NavigationBar";
import AuthPage from "./components/AuthPage";

function App() {
  return (
    <div className="dashboard">
      <NavigationBar />
      <div className="top-section">
        <InputMeal />
        <SearchFood />
      </div>
      <div className="bottom-section">
        <DailyGoals />
        <WeeklyReports />
        <Suggestions />
      </div>

      {/* Define the routes below */}
      <Routes>
        <Route path="/" element={<div />} /> {/* Home or Dashboard route */}
        <Route path="/auth" element={<AuthPage />} /> {/* Login page route */}
      </Routes>
    </div>
  );
}

export default App;
